import{z as T,x as l,o as t,c as n,q as r,j as E,D as e,d as o,s as i,S as A,b as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"SCTP 对照","description":"","frontmatter":{"title":"SCTP 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sctp.md","filePath":"cs/sctp.md","lastUpdated":1791063341000}'),p={name:"cs/sctp.md"};function B(P,a,d,c,S,h){const C=l("Mermaid");return t(),n("div",null,[a[2]||(a[2]=r('<h1 id="sctp-对照" tabindex="-1">SCTP 对照 <a class="header-anchor" href="#sctp-对照" aria-label="Permalink to &quot;SCTP 对照&quot;">​</a></h1><div class="epigraph"><p>SCTP 原生多宿与多流，消息边界保留，四次握手带 cookie 抗 SYN 泛洪；不是 TCP 的选项补丁。</p><footer>—— 据 RFC 9260 SCTP；RFC 4960 历史整理</footer></div><p><a href="/cs/mptcp">MPTCP</a> 在 TCP 上打补丁。<a href="/cs/mptcp">上一课</a> 留下「为何不换协议」。缺口是 <strong>SCTP 对照</strong>：消息、多流无队头阻塞、INIT cookie。本课不把 QUIC 0-RTT 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信令（SS7 over IP）要多宿故障切换、要记录边界。TCP 是字节流，粘包后课才说。SCTP：DATA 块有流 ID，一流失序不挡另一流——对照后课 HTTP/2 与 QUIC。关联（association）可绑多地址。四次握手：INIT-ACK 带 cookie，状态在客户端回 COOKIE-ECHO 后才占 TCB，对象同 SYN cookies，但是一等公民。<span class="marginnote">术语翻译：多宿就是「一条关联同时登记多个网络地址」的手段——主路径断了，数据自动切到备用地址；多流就是「一条连接里开多条互不阻塞的小车道」——一流丢包重传，另一流的消息照常交付，没有 TCP 那种全线排队。</span></p><p>不要把 SCTP 写成互联网默认：NAT 与中间盒支持远差于 TCP/UDP。</p><p><span class="marginnote">RFC 9260 现行。WebRTC 数据通道曾用 SCTP over DTLS。本课对照，不推部署。</span></p><h3 id="原生多流多宿" tabindex="-1">原生多流多宿 <a class="header-anchor" href="#原生多流多宿" aria-label="Permalink to &quot;原生多流多宿&quot;">​</a></h3><p>消息边界保留，cookie 握手抗泛洪。NAT 支持差于 TCP/UDP。Web 路径上 QUIC 更常见。不是默认互联网运输。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表：TCP / MPTCP / SCTP / QUIC：单位、多径、握手、部署。画：多流 → 公共拥塞窗口（或按实现）。与 UDP：SCTP 可靠可选，还有部分可靠扩展点名。</p>',11)),(t(),E(A,null,{default:e(()=>[i(C,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSG%5B%22%E6%B6%88%E6%81%AF%E8%BE%B9%E7%95%8C%22%5D%20--%3E%20STR%5B%22%E5%A4%9A%E6%B5%81%22%5D%0A%20%20STR%20--%3E%20ASSOC%5B%22%E5%A4%9A%E5%AE%BF%E5%85%B3%E8%81%94%22%5D%0A%20%20CK%5B%22INIT%20cookie%22%5D%20--%3E%20ANTI%5B%22%E6%8A%97%E6%B3%9B%E6%B4%AA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[o("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"拥塞仍 AIMD 族，BDP 同样适用。心跳是协议内，比 TCP keepalive 更一等。不走 TSO 惯例路径，卸载少。RTO 与无线误码同样痛。EVPN 等与 SCTP 无关。",-1)),(t(),E(A,null,{default:e(()=>[i(C,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20C1%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%EF%BC%9AINIT%22%5D%20--%3E%20S1%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%EF%BC%9AINIT-ACK%3Cbr%2F%3E%E9%99%84%E5%8A%A0%E5%AF%86%20cookie%EF%BC%8C%E4%B8%8D%E5%8D%A0%20TCB%22%5D%0A%20%20S1%20--%3E%20C2%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%EF%BC%9ACOOKIE-ECHO%22%5D%0A%20%20C2%20--%3E%20V%7B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E9%AA%8C%E8%AF%81%20cookie%22%7D%0A%20%20V%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20EST%5B%22%E6%AD%A4%E5%88%BB%E6%89%8D%E5%BB%BA%20TCB%EF%BC%9A%E5%85%B3%E8%81%94%E5%BB%BA%E7%AB%8B%22%5D%0A%20%20V%20--%3E%7C%22%E4%BC%AA%E9%80%A0%E6%88%96%E8%BF%87%E6%9C%9F%22%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%EF%BC%9A%E6%9C%8D%E5%8A%A1%E5%99%A8%E6%B2%A1%E8%8A%B1%E8%BF%87%E5%86%85%E5%AD%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">cookie 握手可以类比餐厅订位：TCP 三次握手是「客人一喊就先占一张桌子（TCB）」，假客人多了桌子被占光；SCTP 是「先发一张加密订位凭证」，客人带着凭证回来、验过真伪才真正安排座位——伪造者拿不出有效凭证，服务器全程没掏内存。</span></p><p>队头：SCTP 流避免传输 HOL，应用仍可自己造依赖。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SCTP 认证块全文。QUIC 流与 0-RTT 是下一课。后课默认：SCTP 是另一运输；Web 路径上 QUIC 更常见。</p><p>防火墙只放 80/443 时 SCTP 出不去。<span class="marginnote">初学者容易以为「协议更好就该替换 TCP」，实际部署约束先于协议优劣：NAT 与中间盒常按 TCP/UDP 的假设写死，防火墙只放行 80/443 时 SCTP 包根本出不了内网——这也是 QUIC 干脆「伪装成 UDP」的原因之一。</span></p><p>下一课<a href="/cs/quic-streams-0rtt">QUIC 流与 0-RTT</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>消息+多流+多宿是原生能力。</li><li>Cookie 握手抗半开洪泛。</li><li>部署受 NAT/中间盒约束。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9260。</li></ul>',8))])}const I=T(p,[["render",B]]);export{D as __pageData,I as default};
